// Convierte el correo en el mensaje que espera la API (/procesar).
// Funciona con los formatos "simple" y "resolved" del nodo de correo.
const salida = [];

for (const item of $input.all()) {
  const j = item.json;

  // Remitente: puede venir como texto o como objeto
  let de = typeof j.from === "string" ? j.from : (j.from && (j.from.text || j.from.value?.[0]?.address)) || "";

  // Cuerpo: prefiere texto plano; si solo hay HTML, le quita las etiquetas
  let cuerpo = j.textPlain || j.text || "";
  if (!cuerpo && (j.textHtml || j.html)) {
    cuerpo = String(j.textHtml || j.html)
      .replace(/<(style|script)[\s\S]*?<\/\1>/gi, " ")
      .replace(/<br\s*\/?>|<\/p>|<\/div>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">");
  }
  cuerpo = cuerpo.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();

  const asunto = (j.subject || "").trim();
  if (!cuerpo && !asunto) continue; // correo vacío: no hay nada que clasificar

  // La API acepta hasta 5000 caracteres: dejamos margen para el encabezado
  const lineas = [];
  if (de) lineas.push(`De: ${de}`);
  if (asunto) lineas.push(`Asunto: ${asunto}`);
  lineas.push("", cuerpo.slice(0, 4500));
  const mensaje = lineas.join("\n").trim();

  salida.push({ json: { mensaje, origen: "correo" } });
}

return salida;
